void assert_trap_infos_ordered() {
  for (size_t z = 0; z < trap_info.size() - 1; z++) {
    if (trap_info[z + 1] < trap_info[z]) {
      throw std::logic_error(std::format("Trap info out of order: [{}]=({}) < [{}]=({})",
          z + 1, trap_info[z + 1].str(), z, trap_info[z].str()));
    }
  }
}

const TrapInfo* info_for_68k_trap(uint16_t trap_num, uint8_t flags) {
  auto it = std::lower_bound(trap_info.begin(), trap_info.end(), trap_num,
      [](const TrapInfo& ti, uint16_t trap_num) {
        return ti.trap_num < trap_num;
      });

  const TrapInfo* base_match = (it != trap_info.end()) ? &*it : nullptr;
  const TrapInfo* flag_match = nullptr;
  const TrapInfo* condition_match = nullptr;
  for (; (it != trap_info.end()) && (it->trap_num == trap_num); it++) {
    if (!flag_match && (it->flags == flags)) {
      flag_match = &*it;
      break;
    }
    // TODO: Implement conditions here (and delete break from the above condition)
  }

  if (condition_match) {
    return condition_match;
  } else if (flag_match) {
    return flag_match;
  } else {
    return base_match;
  }
}

